def alternateMaxMin(nums):
    a = list(nums)
    n = len(a)
    m = a[-1] + 1
    lo, hi = 0, n - 1
    for i in range(n):
        if i % 2 == 0:
            a[i] += (a[hi] % m) * m
            hi -= 1
        else:
            a[i] += (a[lo] % m) * m
            lo += 1
    return [x // m for x in a]
